/// Returns `true` iff every element of `a` equals `n`.
///
/// Correctness guarantees:
/// - If this returns `true`, then for every valid index `i`, `a[i] == n`.
/// - If this returns `false`, then there exists some valid index `i` with `a[i] != n`.
///
/// No preconditions: works for empty slices (returns `true`).
pub fn all_elements_equal(a: &[i32], n: i32) -> bool {
    a.iter().all(|&x| x == n)
}

